class PaymentProcessorFactory:
    @staticmethod
    def create_processor(payment_type: str, security_code: str, authorizer: SMSAuthorizer = None) -> PaymentProcessor:
        if payment_type == 'debit':
            return DebitPaymentProcessor(security_code, authorizer)
        elif payment_type == 'credit':
            return CreditPaymentProcessor(security_code)
        elif payment_type == 'paypal':
            return PaypalPaymentProcessor(security_code)
        else:
            raise ValueError('Unsupported payment type')
